import { readFile, writeFile } from "node:fs/promises";
const source = await readFile(
  new URL("../shared/video-protocol.js", import.meta.url),
  "utf8",
);
const target = new URL(
  "../browser-extension/video-protocol.js",
  import.meta.url,
);
const generated =
  "// Generated by npm run extension:build. Edit shared/video-protocol.js.\n" +
  source;
if (process.argv.includes("--check")) {
  if ((await readFile(target, "utf8")) !== generated)
    throw new Error(
      "Extension protocol is stale. Run npm run extension:build.",
    );
} else await writeFile(target, generated);
